def count_m(limit):
    count = 0
    for m in range(1, limit + 1):
        if m < 5:
            continue
        # m mod 6 must be 0, 2, 3, or 5
        mod = m % 6
        if mod == 0 or mod == 2 or mod == 3 or mod == 5:
            count += 1
    return count

print(count_m(100))
